&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Bring&amp;nbsp;established&amp;nbsp;familiarity&amp;nbsp;with&amp;nbsp;aircraft&amp;nbsp;certification&amp;nbsp;processes&amp;nbsp;and&amp;nbsp;avionics&amp;nbsp;integration&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
